-- Rottner-Import: weitere Serien und Varianten aus den bereitgestellten Katalogen
-- Keine Katalogpreise übernommen. Lagerstatus initial "Muss bestellt werden".
-- Waffenrechtliche Eignung wird hier nicht als Rechtsauskunft interpretiert.
on conflict (article_number) where article_number is not null and trim(article_number) <> ''
do update set
 model=excluded.model,category=excluded.category,security_standard=excluded.security_standard,
 security_class=excluded.security_class,fire_protection_type=excluded.fire_protection_type,
 fire_minutes=excluded.fire_minutes,fire_standard=excluded.fire_standard,
 insured_private=excluded.insured_private,insured_commercial=excluded.insured_commercial,
 height_mm=excluded.height_mm,width_mm=excluded.width_mm,depth_mm=excluded.depth_mm,
 inner_height_mm=excluded.inner_height_mm,inner_width_mm=excluded.inner_width_mm,inner_depth_mm=excluded.inner_depth_mm,
 weight_kg=excluded.weight_kg,volume_l=excluded.volume_l,lock_type=excluded.lock_type,
 source_reference=excluded.source_reference,source_date=excluded.source_date,
 family_name=excluded.family_name,notes=excluded.notes;
